.darma-loader-darma-b16-defrag-grid { --accent: var(--loader-color, #1d4ed8); --accent-2: var(--loader-secondary-color, #f8fafc); width: var(--loader-size, 118px); height: var(--loader-size, 118px); position: relative; display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(4, 1fr); gap: 4%; }
.darma-loader-darma-b16-defrag-grid span { border-radius: 2px; background: var(--accent-2); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 30%, transparent); animation: darma-loader-darma-b16-defrag-grid-defrag-pack calc(var(--loader-speed, 1s) * 3.2) steps(1, end) infinite; }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * .18); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * 1.44); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(4) { animation-delay: calc(var(--loader-speed, 1s) * .54); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(5) { animation-delay: calc(var(--loader-speed, 1s) * 2.16); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(6) { animation-delay: calc(var(--loader-speed, 1s) * .9); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(7) { animation-delay: calc(var(--loader-speed, 1s) * 1.8); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(8) { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(9) { animation-delay: calc(var(--loader-speed, 1s) * 2.52); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(10) { animation-delay: calc(var(--loader-speed, 1s) * 1.08); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(11) { animation-delay: calc(var(--loader-speed, 1s) * .72); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(12) { animation-delay: calc(var(--loader-speed, 1s) * 2.88); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(13) { animation-delay: calc(var(--loader-speed, 1s) * 1.62); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(14) { animation-delay: calc(var(--loader-speed, 1s) * 2.34); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(15) { animation-delay: calc(var(--loader-speed, 1s) * 1.26); }
.darma-loader-darma-b16-defrag-grid span:nth-of-type(16) { animation-delay: calc(var(--loader-speed, 1s) * 2.7); }
@keyframes darma-loader-darma-b16-defrag-grid-defrag-pack { 0%, 44% { background: var(--accent-2); transform: scale(1); } 45%, 56% { background: color-mix(in srgb, #fff 40%, var(--accent)); transform: scale(.72); } 57%, 100% { background: var(--accent); transform: scale(1); } }

